changes.before:
/* R123H_SIDEBAR_CLEARANCE_BEGIN: padding is still painted by the z=10
 * sidebar over the z=7 dock. A margin reserves the same lane outside its
 * border box; the library's content width and the canvas rectangle stay put.
 */
body:is(.canvas-composition, .v3-mode) #app > .workspace > .sidebar-left {
  margin-inline-end: var(--r123h-dock);
}
/* R123H_SIDEBAR_CLEARANCE_END */

changes.after:
